import type { Tool } from '@modelcontextprotocol/server';
import catalog from '../../docs/agent/relay-tools.json';

/**
 * The relay tool catalog, bundled at build time from docs/agent/relay-tools.json: exactly the definitions
 * the app's hello sends (generated by the app, kept equal by RelayClientTest.relayToolsFileMatchesTheHello;
 * regenerate with RELAY_TOOLS_WRITE=1). Never read at runtime and never edited by hand here.
 */
export const RELAY_TOOLS: Tool[] = catalog.tools as unknown as Tool[];
export const RELAY_TOOL_NAMES = new Set(RELAY_TOOLS.map(tool => tool.name));
export function sameSchema(a: unknown, b: unknown): boolean {
  return JSON.stringify(canonical(a)) === JSON.stringify(canonical(b));
}
function canonical(value: any): any {
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === 'object') return Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])]));
  return value;
}
